using System;using System.IO;using System.Collections.Generic;using System.Windows.Forms;
namespace ScoreModern {public sealed partial class Editor {
 bool pendingDriveChange;readonly Dictionary<char,string> driveDirectories=new Dictionary<char,string>();
 void StartDriveChange(){string directory=Directory.GetCurrentDirectory(),root=Path.GetPathRoot(directory);if(root.Length<2||root[1]!=':')throw new NotSupportedException("DRV requires a Windows drive-letter working directory.");char drive=Char.ToUpperInvariant(root[0]);driveDirectories[drive]=directory;pendingDriveChange=true;Message("Current default drive = "+drive+"\r\nPress new drive letter or <Enter> ->");}
 bool SubmitDriveChange(string text){if(!pendingDriveChange)return false;if(text.Length==0||text=="\r"){if(ContinueScor4Path())return true;pendingDriveChange=false;Message("");return true;}char drive=Char.ToUpperInvariant(text[0]);if(text.Length!=1||drive<'A'||drive>'Z')throw new InvalidDataException("Enter one drive letter.");string directory;if(!driveDirectories.TryGetValue(drive,out directory))directory=Path.GetFullPath(drive+":");if(!Directory.Exists(directory))throw new DirectoryNotFoundException("Drive directory unavailable: "+directory);Directory.SetCurrentDirectory(directory);if(ContinueScor4Path())return true;pendingDriveChange=false;command.Clear();Message("");UpdateClassic();return true;}
 bool DriveChangeKey(KeyEventArgs key){if(!pendingDriveChange)return false;if(key.KeyCode==Keys.Enter||key.KeyCode==Keys.Escape){if(key.KeyCode==Keys.Enter&&ContinueScor4Path()){key.SuppressKeyPress=true;return true;}pendingScor4Path=false;pendingDriveChange=false;command.Clear();Message("");key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
}}
